// wider it uses softly constrained decoding with a boost toward valid continuations.
// This keeps generation aligned with the required step-by-step math format,
// including << >> arithmetic spans, by ensuring every accepted token preserves
// parser validity while allowing early EOS termination.
// CSD_RATIONALE_END
generated := currentPrefix;
helpers.cost := 0;
cost := 0;
var suffix: Prefix := [];
var steps: nat := 0;

